// Generated by prepare_external_hosts.py from the frozen raw host.
`timescale 1ns/1ps
// Reports-only proof adapter. Owner holds I_corners until O_busy falls.
// This module does not yet arbitrate coarse/backend owners in production.
module pcb_raw_geometry_host_external_candidate #(
    parameter integer GEOMETRY_ENTRY=531,
    parameter integer WATCHDOG=2000000
)(
    input wire I_clk,I_rst_n,I_start,I_cancel,
    input wire [315:0] I_corners,
    output wire O_ready,O_busy,
    output reg O_done,O_valid,O_inside,O_convex,
    output reg [8:0] O_error,
    output wire O_engine_cancel,O_engine_host_write,O_engine_start,O_engine_emit_ready,
    output wire [5:0] O_engine_host_index,
    output wire [31:0] O_engine_host_data,
    output wire [15:0] O_engine_entry,
    input wire I_engine_busy,I_engine_done,I_engine_valid,I_engine_host_ready,I_engine_host_done,
    input wire [8:0] I_engine_status,I_engine_error,
    input wire I_engine_emit_valid,
    input wire [8:0] I_engine_emit_tag,
    input wire [31:0] I_engine_emit_d,I_engine_emit_a,I_engine_emit_b
);
    localparam IDLE=0,PRELOAD=1,PRELOAD_WAIT=2,LAUNCH=3,RUN=4,DRAIN=5;
    localparam integer TIMER_BITS=WATCHDOG>1?$clog2(WATCHDOG):1;
    reg [2:0] state;
    reg [3:0] preload;
    reg [TIMER_BITS-1:0] clocks;
    reg seen_emit,malformed;
    reg [8:0] pending_error;
    reg [31:0] preload_data;
    wire engine_busy=I_engine_busy,engine_done=I_engine_done,engine_valid=I_engine_valid;
    wire host_ready=I_engine_host_ready,host_done=I_engine_host_done;
    wire [8:0] engine_status=I_engine_status,engine_error=I_engine_error;
    wire emit_valid=I_engine_emit_valid;
    wire [8:0] emit_tag=I_engine_emit_tag;
    wire [31:0] emit_d=I_engine_emit_d,emit_a=I_engine_emit_a,emit_b=I_engine_emit_b;
    wire abort_now=I_cancel||(I_start&&state!=IDLE)||
        (state!=IDLE&&state!=DRAIN&&clocks>=WATCHDOG-1);
    wire engine_cancel=abort_now||state==DRAIN;
    wire emit_shape=emit_tag==0&&emit_d<=1&&emit_a<=1&&emit_b==0&&!seen_emit;
    assign O_ready=state==IDLE&&!engine_busy&&!I_cancel;
    assign O_busy=state!=IDLE||engine_busy;
    always @* begin
        preload_data=0;
        case(preload)
            0:preload_data=I_corners[31:0];
            1:preload_data={24'd0,I_corners[39:32]};
            2:preload_data=I_corners[71:40];
            3:preload_data={25'd0,I_corners[78:72]};
            4:preload_data=I_corners[110:79];
            5:preload_data={24'd0,I_corners[118:111]};
            6:preload_data=I_corners[150:119];
            7:preload_data={25'd0,I_corners[157:151]};
            8:preload_data=I_corners[189:158];
            9:preload_data={24'd0,I_corners[197:190]};
            10:preload_data=I_corners[229:198];
            11:preload_data={25'd0,I_corners[236:230]};
            12:preload_data=I_corners[268:237];
            13:preload_data={24'd0,I_corners[276:269]};
            14:preload_data=I_corners[308:277];
            15:preload_data={25'd0,I_corners[315:309]};
        endcase
    end
    assign O_engine_cancel=engine_cancel;
    assign O_engine_host_write=state==PRELOAD&&!abort_now;
    assign O_engine_host_index=6'd2+{2'd0,preload};
    assign O_engine_host_data=preload_data;
    assign O_engine_start=state==LAUNCH&&!abort_now;
    assign O_engine_entry=GEOMETRY_ENTRY[15:0];
    assign O_engine_emit_ready=state==RUN&&!abort_now;
    always @(posedge I_clk or negedge I_rst_n) begin
        if(!I_rst_n)begin
            state<=IDLE;preload<=0;clocks<=0;seen_emit<=0;malformed<=0;pending_error<=0;
            O_done<=0;O_valid<=0;O_inside<=0;O_convex<=0;O_error<=0;
        end else begin
            O_done<=0;
            if(state!=IDLE&&state!=DRAIN)clocks<=clocks+1'b1;
            if(state!=IDLE&&state!=DRAIN&&abort_now)begin
                pending_error<=I_cancel?9'h104:I_start?9'h108:9'h109;
                O_valid<=0;O_inside<=0;O_convex<=0;state<=DRAIN;
            end else case(state)
                IDLE:begin
                    if(I_cancel)begin O_valid<=0;O_inside<=0;O_convex<=0;end
                    else if(I_start&&O_ready)begin
                        preload<=0;clocks<=0;seen_emit<=0;malformed<=0;
                        O_valid<=0;O_inside<=0;O_convex<=0;O_error<=0;state<=PRELOAD;
                    end
                end
                PRELOAD:if(host_ready)state<=PRELOAD_WAIT;
                PRELOAD_WAIT:if(host_done)begin
                    if(preload==15)state<=LAUNCH;
                    else begin preload<=preload+1'b1;state<=PRELOAD;end
                end
                LAUNCH:state<=RUN;
                RUN:begin
                    if(emit_valid)begin
                        if(!emit_shape)malformed<=1;
                        else begin seen_emit<=1;O_inside<=emit_d[0];O_convex<=emit_a[0];end
                    end
                    if(engine_done)begin
                        O_done<=1;state<=IDLE;
                        if(engine_valid&&engine_error==0&&engine_status==0&&seen_emit&&!malformed)begin
                            O_valid<=1;O_error<=0;
                        end else begin
                            O_valid<=0;O_inside<=0;O_convex<=0;
                            O_error<=engine_error!=0?engine_error:9'h10A;
                        end
                    end
                end
                DRAIN:if(!engine_busy)begin O_done<=1;O_error<=pending_error;state<=IDLE;end
                default:begin O_done<=1;O_valid<=0;O_inside<=0;O_convex<=0;O_error<=9'h1FF;state<=IDLE;end
            endcase
        end
    end
endmodule
